messages.content:
Generate a standalone C reproducer that triggers this vulnerability:

File: contrib/pds/tif_pdsdirread.c
Line: 1161
Function: ChopUpSingleUncompressedStrip
Bug type: divide-by-zero
CWE: CWE-369
Explanation: rowsperstrip is computed as 8192 / rowbytes without checking if rowbytes (from TIFFVTileSize) is zero. A crafted image can yield rowbytes == 0, leading to a division by zero at line 1161.

Source context:
```c
     1121:                 fp[i] = (float)((uint32_t *)cp)[i];
     1122:             ok = TIFFSetField(tif, dir->tdir_tag, fp);
     1123:             _TIFFfree((char *)fp);
     1124:         }
     1125:     }
     1126:     if (cp)
     1127:         _TIFFfree(cp);
     1128:     return (ok);
     1129: }
     1130: #endif
     1131: 
     1132: #if STRIPCHOP_SUPPORT
     1133: /*
     1134:  * Replace a single strip (tile) of uncompressed data by
     1135:  * multiple strips (tiles), each approximately 8Kbytes.
     1136:  * This is useful for dealing with large images or
     1137:  * for dealing with machines with a limited amount
     1138:  * memory.
     1139:  */
     1140: static void ChopUpSingleUncompressedStrip(TIFF *tif)
     1141: {
     1142:     register TIFFDirectory *td = &tif->tif_dir;
     1143:     uint32_t bytecount = td->td_stripbytecount[0];
     1144:     uint32_t offset = td->td_stripoffset[0];
     1145:     tsize_t rowbytes = TIFFVTileSize(tif, 1), stripbytes;
     1146:     tstrip_t strip, nstrips, rowsperstrip;
     1147:     uint32_t *newcounts;
     1148:     uint32_t *newoffsets;
     1149: 
     1150:     /*
     1151:      * Make the rows hold at least one
     1152:      * scanline, but fill 8k if possible.
     1153:      */
     1154:     if (rowbytes > 8192)
     1155:     {
     1156:         stripbytes = rowbytes;
     1157:         rowsperstrip = 1;
     1158:     }
     1159:     else
     1160:     {
>>>  1161:         rowsperstrip = 8192 / rowbytes;
     1162:         stripbytes = rowbytes * rowsperstrip;
     1163:     }
     1164:     /* never increase the number of strips in an image */
     1165:     if (rowsperstrip >= td->td_rowsperstrip)
     1166:         return;
     1167:     nstrips = (tstrip_t)TIFFhowmany(bytecount, stripbytes);
     1168:     newcounts =
     1169:         (uint32_t *)CheckMalloc(tif, nstrips * sizeof(uint32_t),
     1170:                                 "for chopped \"StripByteCounts\" array");
     1171:     newoffsets = (uint32_t *)CheckMalloc(tif, nstrips * sizeof(uint32_t),
     1172:                                          "for chopped \"StripOffsets\" array");
     1173:     if (newcounts == NULL || newoffsets == NULL)
     1174:     {
     1175:         /*
     1176:          * Unable to allocate new strip information, give
     1177:          * up and use the original one strip information.
     1178:          */
     1179:         if (newcounts != NULL)
     1180:             _TIFFfree(newcounts);
     1181:         if (newoffsets != NULL)
     1182:             _TIFFfree(newoffsets);
     1183:         return;
     1184:     }
     1185:     /*
     1186:      * Fill the strip information arrays with
     1187:      * new bytecounts and offsets that reflect
     1188:      * the broken-up format.
     1189:      */
     1190:     for (strip = 0; strip < nstrips; strip++)
     1191:     {
     1192:         if (stripbytes > bytecount)
     1193:             stripbytes = bytecount;
     1194:         newcounts[strip] = stripbytes;
     1195:         newoffsets[strip] = offset;
     1196:         offset += stripbytes;
     1197:         bytecount -= stripbytes;
     1198:     }
     1199:     /*
     1200:      * Replace old single strip info with multi-strip info.
     1201:      */
```

The reproducer will be compiled with:
  clang -fsanitize=address -g -O0 -I/tmp/libtiff_upstream reproducer.c -L/tmp/libtiff_upstream/build/.libs -ltiff -lm

The project source root is: /tmp/libtiff_upstream
